/**
 * @brief 检查归一化温度值是否超出对应物理通道的合理量程（热床 5~130°C，喷头 5~300°C）
 * @param source_node 采样源节点编号（1=热床/MC，2=喷头/TH）
 * @param millic 毫摄氏度温度值
 * @return bool 超出物理合理量程返回 true，否则返回 false
 */
static bool is_physical_temp_out_of_range(uint8_t source_node, int32_t millic) {
    if (millic == AISOC_TEMP_MILLIC_OFFLINE || millic == AISOC_TEMP_MILLIC_FAULT) {
        return false;
    }
    if (source_node == 1U) {
        return (millic < AISOC_BED_VALID_MIN_MILLIC) || (millic > AISOC_BED_VALID_MAX_MILLIC);
    }
    if (source_node == 2U) {
        return (millic < AISOC_NOZZLE_VALID_MIN_MILLIC) || (millic > AISOC_NOZZLE_VALID_MAX_MILLIC);
    }
    return false;
}

/**
 * @brief 根据温度哨兵值与传感器状态评估单次采样的数据质量等级
 * @param millic 毫摄氏度温度值
 * @param sensor_status 传感器硬件状态码
 * @return uint32_t 质量等级枚举值
 */
static uint32_t eval_sample_quality(int32_t millic, uint32_t sensor_status) {
    if (millic == AISOC_TEMP_MILLIC_FAULT) {
        return (uint32_t)AISOC_QUALITY_FAULT;
    }
    if (millic == AISOC_TEMP_MILLIC_OFFLINE) {
        return (uint32_t)AISOC_QUALITY_STALE;
    }
    if (sensor_status != (uint32_t)AISOC_SENSOR_OK) {
        return (uint32_t)AISOC_QUALITY_FAULT;
    }
    return (uint32_t)AISOC_QUALITY_FRESH;
}

/**
 * @brief 综合双节点温度与版本在线状态更新顶层 system_status_desc 与 device_state
 * @param state 设备管理服务状态结构体指针
 */
static void update_system_status_desc(device_manager_state_t* state) {
    if (state == nullptr || state->is_fault) {
        return;
    }
    const dev_state_version_binding_t* b = find_version_binding(state);
    const bool mc_offline = (state->snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_OFFLINE) ||
                            (b != nullptr && b->mc_ver.is_valid && b->mc_ver.status == DEV_VER_STATUS_OFFLINE);
    const bool th_offline = (state->snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_OFFLINE) ||
                            (b != nullptr && b->th_ver.is_valid && b->th_ver.status == DEV_VER_STATUS_OFFLINE);

    if (mc_offline && th_offline) {
        strncpy(state->snapshot.system_status_desc, "OFFLINE", sizeof(state->snapshot.system_status_desc) - 1U);
        return;
    }
    if (mc_offline || th_offline) {
        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
        return;
    }

    const bool b_fault = (state->snapshot.bed_sensor_status != (uint32_t)AISOC_SENSOR_OK) ||
                         (state->snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_FAULT) ||
                         (state->snapshot.bed_quality == (uint32_t)AISOC_QUALITY_FAULT);
    const bool t_fault = (state->snapshot.tool_sensor_status != (uint32_t)AISOC_SENSOR_OK) ||
                         (state->snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_FAULT) ||
                         (state->snapshot.tool_quality == (uint32_t)AISOC_QUALITY_FAULT);
    if (b_fault || t_fault) {
        strncpy(state->snapshot.system_status_desc, "DEGRADED", sizeof(state->snapshot.system_status_desc) - 1U);
        return;
    }
    const bool b_ok = (state->snapshot.bed_sensor_status == (uint32_t)AISOC_SENSOR_OK) &&
                      (state->snapshot.bed_quality == (uint32_t)AISOC_QUALITY_FRESH);
    const bool t_ok = (state->snapshot.tool_sensor_status == (uint32_t)AISOC_SENSOR_OK) &&
                      (state->snapshot.tool_quality == (uint32_t)AISOC_QUALITY_FRESH);
    const char* desc = (b_ok && t_ok) ? "NORMAL" : "DEGRADED";
    strncpy(state->snapshot.system_status_desc, desc, sizeof(state->snapshot.system_status_desc) - 1U);
}

/**
 * @brief 将毫摄氏度整数格式化为 JSON 摄氏度浮点字符串（哨兵值格式化为 null）
 * @param millic 毫摄氏度温度值
 * @param out_buf 输出字符串缓冲区
 * @param cap 输出缓冲区容量
 */
static void format_temp_c_val(int32_t millic, char* out_buf, size_t cap) {
    if (out_buf == nullptr || cap == 0U) {
        return;
    }
    if (millic == AISOC_TEMP_MILLIC_FAULT || millic == AISOC_TEMP_MILLIC_OFFLINE) {
        snprintf(out_buf, cap, "null");
    } else {
        const double deg = (double)millic / 1000.0;
        snprintf(out_buf, cap, "%.1f", deg);
    }
}

/**
 * @brief 接收并归一化单次原始温度采样，执行物理量程门禁与质量评级
 * @param state 设备管理服务状态结构体指针
 * @param sample 原始温度采样数据只读指针
 * @return aisoc_dev_status_t 成功返回 AISOC_DEV_OK
 */
aisoc_dev_status_t dev_state_update_raw_sample(
    device_manager_state_t* state,
    const aisoc_raw_temp_t* sample
) {
    if (state == nullptr || sample == nullptr) {
        return AISOC_DEV_ERR_NULL_PTR;
    }
    state->snapshot.timestamp_ns = sample->host_received_ns;
    int32_t norm_millic = sample->temperature_millic;
    uint32_t norm_status = sample->sensor_status;
    const bool out_of_range = is_physical_temp_out_of_range(sample->source_node, norm_millic);
    if (out_of_range) {
        norm_millic = AISOC_TEMP_MILLIC_FAULT;
        if (norm_status == (uint32_t)AISOC_SENSOR_OK) {
            norm_status = (uint32_t)AISOC_SENSOR_OPEN;
        }
    }
    dev_state_version_binding_t* vb = find_or_create_version_binding(state);
    if (sample->source_node == 1U) {
        state->bed_raw_adc = sample->raw_adc;
        state->snapshot.bed_temp_millic = norm_millic;
        state->snapshot.bed_sensor_status = norm_status;
        state->snapshot.bed_quality = eval_sample_quality(norm_millic, norm_status);
        state->last_bed_rx_ns = sample->host_received_ns;
        if (vb != nullptr && vb->mc_ver.is_valid) {
            vb->mc_ver.last_update_ns = sample->host_received_ns;
            vb->mc_ver.status = DEV_VER_STATUS_ONLINE;
        }
    } else if (sample->source_node == 2U) {
        state->tool_raw_adc = sample->raw_adc;
        state->snapshot.tool_temp_millic = norm_millic;
        state->snapshot.tool_sensor_status = norm_status;
        state->snapshot.tool_quality = eval_sample_quality(norm_millic, norm_status);
        state->last_tool_rx_ns = sample->host_received_ns;
        if (vb != nullptr && vb->th_ver.is_valid) {
            vb->th_ver.last_update_ns = sample->host_received_ns;
            vb->th_ver.status = DEV_VER_STATUS_ONLINE;
        }
    }

    update_system_status_desc(state);
    if (out_of_range) {
        state->is_fault = true;
        strncpy(state->device_state, "FAULT", sizeof(state->device_state) - 1U);
    }
    state->snapshot.generation_id++;
    state->generation_id++;
    return AISOC_DEV_OK;
}

/**
 * @brief 评估单通道传感器采样的新鲜度，超 3.0s 或节点离线时强制打入 OFFLINE 哨兵值
 * @param state 设备管理服务状态结构体指针
 * @param node 节点编号（1=热床/MC，2=喷头/TH）
 * @param now_ns 当前单调时钟纳秒戳
 * @param node_offline 对应节点是否已判定为离线
 */
static void eval_sensor_freshness(
    device_manager_state_t* state,
    uint8_t node,
    uint64_t now_ns,
    bool node_offline
) {
    if (state == nullptr) {
        return;
    }
    const uint64_t last_rx = (node == 1U) ? state->last_bed_rx_ns : state->last_tool_rx_ns;
    int32_t* p_temp = (node == 1U) ? &state->snapshot.bed_temp_millic : &state->snapshot.tool_temp_millic;
    uint32_t* p_st = (node == 1U) ? &state->snapshot.bed_sensor_status : &state->snapshot.tool_sensor_status;
    uint32_t* p_qual = (node == 1U) ? &state->snapshot.bed_quality : &state->snapshot.tool_quality;

    if (last_rx > 0U) {
        const uint64_t elapsed_ns = (now_ns >= last_rx) ? (now_ns - last_rx) : 0U;
        const uint32_t elapsed_ms = (uint32_t)(elapsed_ns / 1000000ULL);
        aisoc_data_quality_t q = AISOC_QUALITY_UNKNOWN;
        telemetry_eval_data_quality(elapsed_ms, (aisoc_sensor_status_t)(*p_st), &q);
        if (elapsed_ms >= AISOC_FRESHNESS_FAULT_MS || node_offline) {
            *p_temp = AISOC_TEMP_MILLIC_OFFLINE;
            *p_st = (uint32_t)AISOC_SENSOR_TIMEOUT;
            *p_qual = (uint32_t)AISOC_QUALITY_FAULT;
        } else if (*p_temp == AISOC_TEMP_MILLIC_FAULT) {
            *p_qual = (uint32_t)AISOC_QUALITY_FAULT;
        } else if (*p_temp == AISOC_TEMP_MILLIC_OFFLINE && q == AISOC_QUALITY_FRESH) {
            *p_qual = (uint32_t)AISOC_QUALITY_STALE;
        } else {
            *p_qual = (uint32_t)q;
        }
    } else {
        *p_temp = AISOC_TEMP_MILLIC_OFFLINE;
        if (node_offline) {
            *p_st = (uint32_t)AISOC_SENSOR_TIMEOUT;
            *p_qual = (uint32_t)AISOC_QUALITY_FAULT;
        }
    }
}

/**
 * @brief 评估热床与喷头温度采样的新鲜度，超 1.5s 置 STALE，超 3.0s 置 OFFLINE/FAULT
 * @param state 设备管理服务状态结构体指针
 * @param now_ns 当前单调时钟纳秒戳
 * @return aisoc_dev_status_t 成功返回 AISOC_DEV_OK
 */
aisoc_dev_status_t dev_state_eval_freshness(
    device_manager_state_t* state,
    uint64_t now_ns
) {
    if (state == nullptr) {
        return AISOC_DEV_ERR_NULL_PTR;
    }
    const dev_state_version_binding_t* vb = find_version_binding(state);
    const bool mc_off = (vb != nullptr && vb->mc_ver.is_valid && vb->mc_ver.status == DEV_VER_STATUS_OFFLINE);
    const bool th_off = (vb != nullptr && vb->th_ver.is_valid && vb->th_ver.status == DEV_VER_STATUS_OFFLINE);

    eval_sensor_freshness(state, 1U, now_ns, mc_off);
    eval_sensor_freshness(state, 2U, now_ns, th_off);
    update_system_status_desc(state);
    return AISOC_DEV_OK;
}

