/**
 * @brief 校验原始温度采样是否处于正常状态且位于物理合理量程内（热床 5~130°C，喷头 5~300°C）
 * @param s 原始温度采样只读指针
 * @return bool 有效且在物理量程内返回 true，否则返回 false
 */
static bool is_sample_valid(const aisoc_raw_temp_t* s) {
    if (s == nullptr) {
        return false;
    }
    if (s->sensor_status != (uint32_t)AISOC_SENSOR_OK) {
        return false;
    }
    if (s->temperature_millic == AISOC_TEMP_MILLIC_FAULT ||
        s->temperature_millic == AISOC_TEMP_MILLIC_OFFLINE) {
        return false;
    }
    if (s->source_node == 1U) {
        return (s->temperature_millic >= AISOC_BED_VALID_MIN_MILLIC) &&
               (s->temperature_millic <= AISOC_BED_VALID_MAX_MILLIC);
    }
    if (s->source_node == 2U) {
        return (s->temperature_millic >= AISOC_NOZZLE_VALID_MIN_MILLIC) &&
               (s->temperature_millic <= AISOC_NOZZLE_VALID_MAX_MILLIC);
    }
    return true;
}

