/**
 * @brief 验证版本新鲜度 1.5s ONLINE / 3.0s OFFLINE 衰退与顶层状态联动
 */
static bool test_unit_version_freshness_decay_and_system_status() {
    device_manager_state_t state;
    state.generation_id = 1U;
    dev_state_init_snapshot(&state);

    const uint64_t t0 = 10000000000ULL;
    aisoc_dev_mcu_version_t v = {};
    v.proto_major = 2U;
    v.status = DEV_VER_STATUS_ONLINE;
    dev_state_update_mcu_version(&state, "MC", &v, t0);
    dev_state_update_mcu_version(&state, "TH", &v, t0);

    /* Delta 1.0s: < 1.5s -> ONLINE */
    dev_state_eval_version_freshness(&state, t0 + 1000000000ULL);
    char ver_json[1024] = {0};
    dev_state_get_version_json(&state, ver_json, sizeof(ver_json));
    TEST_CHECK(strstr(ver_json, "\"mc\":{\"valid\":true,\"status\":\"ONLINE\"") != nullptr, "MC ONLINE < 1.5s");
    TEST_CHECK(strstr(ver_json, "\"th\":{\"valid\":true,\"status\":\"ONLINE\"") != nullptr, "TH ONLINE < 1.5s");

    /* Delta 2.0s: 1.5s <= Delta < 3.0s -> STALE */
    dev_state_eval_version_freshness(&state, t0 + 2000000000ULL);
    std::memset(ver_json, 0, sizeof(ver_json));
    dev_state_get_version_json(&state, ver_json, sizeof(ver_json));
    TEST_CHECK(strstr(ver_json, "\"mc\":{\"valid\":true,\"status\":\"STALE\"") != nullptr, "MC STALE at 2.0s");
    TEST_CHECK(strstr(ver_json, "\"th\":{\"valid\":true,\"status\":\"STALE\"") != nullptr, "TH STALE at 2.0s");

    /* Delta 3.1s: >= 3.0s -> OFFLINE */
    dev_state_eval_version_freshness(&state, t0 + 3100000000ULL);
    std::memset(ver_json, 0, sizeof(ver_json));
    dev_state_get_version_json(&state, ver_json, sizeof(ver_json));
    TEST_CHECK(strstr(ver_json, "\"mc\":{\"valid\":true,\"status\":\"OFFLINE\"") != nullptr, "MC OFFLINE at 3.1s");
    TEST_CHECK(strstr(ver_json, "\"th\":{\"valid\":true,\"status\":\"OFFLINE\"") != nullptr, "TH OFFLINE at 3.1s");
    TEST_CHECK(strcmp(state.snapshot.system_status_desc, "OFFLINE") == 0, "System status OFFLINE when both version offline");
    return true;
}

