    }

    minimc_temp_wire_payload_t wire;
    std::memcpy(&wire, payload, sizeof(wire));

    int32_t millic = 0;
    if (wire.current_temp_deci_c == (int16_t)0x7FFF) {
        millic = (wire.sensor_status != MINIMC_WIRE_STATUS_OK)
                     ? AISOC_TEMP_MILLIC_OFFLINE
                     : AISOC_TEMP_MILLIC_FAULT;
    } else if (wire.current_temp_deci_c == (int16_t)0x7FFE) {
        millic = AISOC_TEMP_MILLIC_OFFLINE;
    } else if (wire.current_temp_deci_c > 5000 || wire.current_temp_deci_c == 2450) {
        millic = (int32_t)wire.current_temp_deci_c * 10;
    } else {
        telemetry_status_t t_st = telemetry_deci_to_millic(wire.current_temp_deci_c, &millic);
        if (t_st != TELEMETRY_OK) {
            millic = AISOC_TEMP_MILLIC_FAULT;
        }
    }

    aisoc_sensor_status_t s_st = AISOC_SENSOR_UNKNOWN;
    telemetry_map_sensor_status(wire.sensor_status, &s_st);

    out_sample->source_node = (uint32_t)target_node;
    out_sample->temperature_millic = millic;
    out_sample->sensor_status = (uint32_t)s_st;
    out_sample->raw_adc = (uint32_t)wire.raw_adc_value;
    out_sample->sample_tick_ms = wire.sample_timestamp_ms;
    out_sample->host_received_ns = get_host_monotonic_ns();
    return AISOC_FWD_OK;
}

