/**
 * @brief DDS 原始温度采样订阅回调：更新权威快照并向 DDS 与 D-Bus 广播更新事件
 * @param sample 接收到的原始温度采样只读指针
 * @param user_data 用户上下文指针（指向 device_manager_state_t）
 */
static void on_dds_raw_temp_cb(const aisoc_raw_temp_t* sample, void* user_data) {
    if (sample == nullptr || user_data == nullptr) {
        return;
    }
    device_manager_state_t* state = (device_manager_state_t*)user_data;

    pthread_mutex_lock(&state->state_mutex);
    if (is_sample_valid(sample)) {
        sync_version_on_sample(state, sample->source_node, sample->host_received_ns);
    }
    dev_state_update_raw_sample(state, sample);

    if (state->dds_pub_snapshot != nullptr) {
        aisoc_dds_publish_temp_snapshot(state->dds_pub_snapshot, &state->snapshot);
    }
    const uint32_t gen_id = state->snapshot.generation_id;
    const uint64_t ts_ns = state->snapshot.timestamp_ns;
    pthread_mutex_unlock(&state->state_mutex);

    std::printf("[DEVICE_MGR DEBUG] DDS RX: node=%u, temp=%d millic (%.1f C) -> Snapshot GEN=%u (%s)\n",
                sample->source_node, sample->temperature_millic, (double)sample->temperature_millic / 1000.0,
                gen_id, state->snapshot.system_status_desc);
    std::fflush(stdout);

    TEST_CHECK(strstr(ver_json, "\"git_commit\":\"0x12345678\"") != nullptr, "MC git commit");
    TEST_CHECK(strstr(ver_json, "\"git_commit\":\"0x87654321\"") != nullptr, "TH git commit");

    char snap_json[1024] = {0};
    TEST_CHECK(dev_state_get_snapshot_json(&state, snap_json, sizeof(snap_json)) == AISOC_DEV_OK, "Get snapshot json OK");
    TEST_CHECK(strstr(snap_json, "\"devices\":{\"mc\":{") != nullptr, "Snapshot contains devices");
    TEST_CHECK(strstr(snap_json, "\"bed\":{") != nullptr, "Snapshot contains bed");
    TEST_CHECK(strstr(snap_json, "\"tool\":{") != nullptr, "Snapshot contains tool");
    return true;
}

/**
