 */
static bool test_unit_initial_offline_no_fake_online() {
    device_manager_state_t state;
    state.generation_id = 1U;
    dev_state_init_snapshot(&state);

    dev_state_eval_version_freshness(&state, 1000ULL);
    TEST_CHECK(strcmp(state.snapshot.system_status_desc, "OFFLINE") == 0, "System status initially OFFLINE");

    char ver_json[1024] = {0};
    TEST_CHECK(dev_state_get_version_json(&state, ver_json, sizeof(ver_json)) == AISOC_DEV_OK, "Version JSON OK");
    TEST_CHECK(strstr(ver_json, "\"mc\":{\"valid\":false,\"status\":\"OFFLINE\"") != nullptr, "MC initially OFFLINE");
    TEST_CHECK(strstr(ver_json, "\"th\":{\"valid\":false,\"status\":\"OFFLINE\"") != nullptr, "TH initially OFFLINE");
    TEST_CHECK(strstr(ver_json, "ONLINE") == nullptr, "No fake ONLINE present in version JSON");
    return true;
}

/**
 * @brief 验证 3.0s 温度采样超时衰退为 OFFLINE 哨兵值（2147483646）及 raw_adc 映射
 */
static bool test_unit_freshness_timeout_and_offline_sentinel() {
    device_manager_state_t state;
    state.generation_id = 1U;
    dev_state_init_snapshot(&state);

    const uint64_t t0 = 1000000000ULL;
    aisoc_raw_temp_t s1 = {};
    s1.source_node = 1U;
    s1.temperature_millic = 60000;
    s1.sensor_status = AISOC_SENSOR_OK;
    s1.raw_adc = 2048U;
    s1.host_received_ns = t0;
    dev_state_update_raw_sample(&state, &s1);

    aisoc_raw_temp_t s2 = {};
    s2.source_node = 2U;
    s2.temperature_millic = 210000;
    s2.sensor_status = AISOC_SENSOR_OK;
    s2.raw_adc = 1920U;
    s2.host_received_ns = t0;
    dev_state_update_raw_sample(&state, &s2);

    TEST_CHECK(strcmp(state.snapshot.system_status_desc, "NORMAL") == 0, "System status initially NORMAL");
    char snap_json[1024] = {0};
    dev_state_get_snapshot_json(&state, snap_json, sizeof(snap_json));
    TEST_CHECK(strstr(snap_json, "\"raw_adc\":2048") != nullptr, "Bed raw_adc 2048 in snapshot JSON");
    TEST_CHECK(strstr(snap_json, "\"raw_adc\":1920") != nullptr, "Tool raw_adc 1920 in snapshot JSON");

    /* Single node timeout: 3.1 seconds later (>= 3.0s FAULT threshold) for Bed only */
    const uint64_t t_bed_timeout = t0 + 3100000000ULL;
    s2.host_received_ns = t_bed_timeout;
    dev_state_update_raw_sample(&state, &s2);
    dev_state_eval_freshness(&state, t_bed_timeout);

    TEST_CHECK(state.snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_OFFLINE, "Bed timed out to OFFLINE sentinel");
    TEST_CHECK(state.snapshot.bed_sensor_status == (uint32_t)AISOC_SENSOR_TIMEOUT, "Bed status TIMEOUT on 3.1s");
    TEST_CHECK(state.snapshot.bed_quality == (uint32_t)AISOC_QUALITY_FAULT, "Bed quality FAULT on timeout");
    TEST_CHECK(state.snapshot.tool_temp_millic == 210000, "Tool still fresh 210000");
    TEST_CHECK(strcmp(state.snapshot.system_status_desc, "DEGRADED") == 0, "Single node timeout -> DEGRADED");

    /* Both nodes timeout: 3.1 seconds after Tool's last sample */
    const uint64_t t_all_timeout = t_bed_timeout + 3100000000ULL;
    dev_state_eval_freshness(&state, t_all_timeout);
    TEST_CHECK(state.snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_OFFLINE, "Bed still OFFLINE sentinel");
    TEST_CHECK(state.snapshot.tool_temp_millic == AISOC_TEMP_MILLIC_OFFLINE, "Tool timed out to OFFLINE sentinel");
    TEST_CHECK(strcmp(state.snapshot.system_status_desc, "OFFLINE") == 0, "Both nodes timed out -> OFFLINE");

    /* ISS-20261105-011: Bed out-of-range (300.0C = 300000 millic > 130000) forced to FAULT */
    s1.temperature_millic = 300000;
    s1.sensor_status = AISOC_SENSOR_OK;
    s1.host_received_ns = t_all_timeout + 1000000ULL;
    dev_state_update_raw_sample(&state, &s1);
    TEST_CHECK(state.snapshot.bed_temp_millic == AISOC_TEMP_MILLIC_FAULT, "Bed 300C forced to FAULT sentinel");
    TEST_CHECK(state.snapshot.bed_sensor_status == (uint32_t)AISOC_SENSOR_OPEN, "Bed 300C status forced to OPEN");
    TEST_CHECK(state.is_fault == true, "Device state is_fault set on bed over-range");
    return true;
}

